/**
 * Model PortalAccount
 * 
 */
export type PortalAccount = $Result.DefaultSelection<Prisma.$PortalAccountPayload>
/**
 * Model PortalUsernameAlias
 * Alternate login usernames (e.g. legacy portal username before HRIS merge).
 */
export type PortalUsernameAlias = $Result.DefaultSelection<Prisma.$PortalUsernameAliasPayload>
/**
 * Model PortalMergeMapping
 * Explicit PortalAccount ↔ merged_users.source_user_id mapping + legacy identifiers.
 */
export type PortalMergeMapping = $Result.DefaultSelection<Prisma.$PortalMergeMappingPayload>
/**
 * Model Company
 * Company directory (access boundary / tenant). Physical table is `teams` for
 * historical reasons; org-chart *Teams* live in `org_chart_sections`.
 * Managed in SuperAdmin Settings → Companies. Archive = `isActive: false`.
 */
export type Company = $Result.DefaultSelection<Prisma.$CompanyPayload>
/**
 * Model UserCompany
 * Company access membership (IAM). A user may belong to many companies; exactly
 * one membership is the default. `PortalAccount.staffDesignatedCompanyId` mirrors
 * the default membership for legacy readers.
 */
export type UserCompany = $Result.DefaultSelection<Prisma.$UserCompanyPayload>
/**
 * Model Agent
 * 
 */
export type Agent = $Result.DefaultSelection<Prisma.$AgentPayload>
/**
 * Model SlaPolicy
 * 
 */
export type SlaPolicy = $Result.DefaultSelection<Prisma.$SlaPolicyPayload>
/**
 * Model EscalationTrigger
 * 
 */
export type EscalationTrigger = $Result.DefaultSelection<Prisma.$EscalationTriggerPayload>
/**
 * Model OrgChartNode
 * Organizational chart node. People only: every node is a staff member from the
 * roster (MergedUser in the secondary DB), snapshotted so the chart survives roster drift.
 */
export type OrgChartNode = $Result.DefaultSelection<Prisma.$OrgChartNodePayload>
/**
 * Model OrgChartEitherOrLink
 * Undirected either/or link between two org-chart people.
 * Approvals that hit either node may be satisfied by either linked person.
 * Children may hang under the pair via OrgChartNode.parentEitherOrLinkId.
 */
export type OrgChartEitherOrLink = $Result.DefaultSelection<Prisma.$OrgChartEitherOrLinkPayload>
/**
 * Model OrgChartSection
 * Org-chart **Team** (UI: "Team"): a group of people inside one company.
 * Source of truth for teams and team membership (`OrgChartNodeSectionMembership`).
 * Teams nest via parentId (a parent may belong to another company, so group-wide
 * reporting lines survive) or report to a person via reportsToNodeId.
 */
export type OrgChartSection = $Result.DefaultSelection<Prisma.$OrgChartSectionPayload>
/**
 * Model OrgChartSectionRole
 * Custom org roles defined for a section (e.g. Deputy, Coordinator, SME).
 * Distinct from the singleton section head (OrgChartSection.headNodeId).
 */
export type OrgChartSectionRole = $Result.DefaultSelection<Prisma.$OrgChartSectionRolePayload>
/**
 * Model OrgChartNodeSectionMembership
 * Additional section memberships for a single org-chart member.
 * OrgChartNode.sectionId remains the primary section for backward-compatible labels.
 */
export type OrgChartNodeSectionMembership = $Result.DefaultSelection<Prisma.$OrgChartNodeSectionMembershipPayload>
/**
 * Model Department
 * Deprecated HRIS department snapshot (logo sync only). Not a product concept:
 * org groups are Teams (`OrgChartSection`). Nothing in the app reads this table.
 */
export type Department = $Result.DefaultSelection<Prisma.$DepartmentPayload>
/**
 * Model Position
 * Catalog of business positions (RA/AP levels, RFP roles, etc.).
 */
export type Position = $Result.DefaultSelection<Prisma.$PositionPayload>
/**
 * Model PositionAssignment
 * Who holds a position (optionally scoped by company). Supports acting assignments later.
 */
export type PositionAssignment = $Result.DefaultSelection<Prisma.$PositionAssignmentPayload>
/**
 * Model Ticket
 * 
 */
export type Ticket = $Result.DefaultSelection<Prisma.$TicketPayload>
/**
 * Model TicketActivity
 * 
 */
export type TicketActivity = $Result.DefaultSelection<Prisma.$TicketActivityPayload>
/**
 * Model TicketMessage
 * 
 */
export type TicketMessage = $Result.DefaultSelection<Prisma.$TicketMessagePayload>
/**
 * Model ChatMessage
 * Real-time request chat (one thread per ticket). Separate from legacy TicketMessage.
 */
export type ChatMessage = $Result.DefaultSelection<Prisma.$ChatMessagePayload>
/**
 * Model ChatMessageRead
 * 
 */
export type ChatMessageRead = $Result.DefaultSelection<Prisma.$ChatMessageReadPayload>
/**
 * Model TicketFeedback
 * 
 */
export type TicketFeedback = $Result.DefaultSelection<Prisma.$TicketFeedbackPayload>
/**
 * Model KpiMaintenance
 * 
 */
export type KpiMaintenance = $Result.DefaultSelection<Prisma.$KpiMaintenancePayload>
/**
 * Model KpiMaintenanceActivity
 * 
 */
export type KpiMaintenanceActivity = $Result.DefaultSelection<Prisma.$KpiMaintenanceActivityPayload>
/**
 * Model TravelOrder
 * Field Assignment — Work Plan for Management Approval (legacy Travel Order rows kept readable).
 */
export type TravelOrder = $Result.DefaultSelection<Prisma.$TravelOrderPayload>
/**
 * Model TravelOrderLocation
 * 
 */
export type TravelOrderLocation = $Result.DefaultSelection<Prisma.$TravelOrderLocationPayload>
/**
 * Model KpiMaintenancePeriodSnapshot
 * 
 */
export type KpiMaintenancePeriodSnapshot = $Result.DefaultSelection<Prisma.$KpiMaintenancePeriodSnapshotPayload>
/**
 * Model HelpdeskCsvTicket
 * 
 */
export type HelpdeskCsvTicket = $Result.DefaultSelection<Prisma.$HelpdeskCsvTicketPayload>
/**
 * Model TaskItem
 * 
 */
export type TaskItem = $Result.DefaultSelection<Prisma.$TaskItemPayload>
/**
 * Model TaskActivity
 * 
 */
export type TaskActivity = $Result.DefaultSelection<Prisma.$TaskActivityPayload>
/**
 * Model AccountActionRequest
 * 
 */
export type AccountActionRequest = $Result.DefaultSelection<Prisma.$AccountActionRequestPayload>
/**
 * Model PatchNote
 * Changelog / release notes shown in the header Patch Notes modal.
 */
export type PatchNote = $Result.DefaultSelection<Prisma.$PatchNotePayload>
/**
 * Model UserPatchNoteView
 * Tracks which merge-DB users have read a given patch note.
 */
export type UserPatchNoteView = $Result.DefaultSelection<Prisma.$UserPatchNoteViewPayload>
/**
 * Model PlatformSetting
 * Key/value JSON settings for platform-wide SuperAdmin configuration.
 */
export type PlatformSetting = $Result.DefaultSelection<Prisma.$PlatformSettingPayload>
/**
 * Model HrisUser
 * Read-only snapshot of merged / HRIS users, replaced on every merged-dump import.
 * The app reads HRIS identity (roster, org-chart labels) from here, never from the merged DB.
 */
export type HrisUser = $Result.DefaultSelection<Prisma.$HrisUserPayload>
/**
 * Model Role
 * RBAC role. System roles (super_admin, admin, employee) cannot be archived.
 */
export type Role = $Result.DefaultSelection<Prisma.$RolePayload>
/**
 * Model Permission
 * Permission catalog row (`<resource>.<action>`), seeded from code.
 */
export type Permission = $Result.DefaultSelection<Prisma.$PermissionPayload>
/**
 * Model RolePermission
 * Role grant. Row presence = allow; absence = deny.
 */
export type RolePermission = $Result.DefaultSelection<Prisma.$RolePermissionPayload>
/**
 * Model RequestBoardColumn
 * Customizable Request Board lanes (legacy global seed/template).
 * Live board UI now uses per-user layouts in `request_board_user_layouts`.
 */
export type RequestBoardColumn = $Result.DefaultSelection<Prisma.$RequestBoardColumnPayload>
/**
 * Model RequestBoardUserLayout
 * Per-account Request Board column layout (names, order, personal custom boards).
 */
export type RequestBoardUserLayout = $Result.DefaultSelection<Prisma.$RequestBoardUserLayoutPayload>

